package app.yydarlinker.deepseekcaptions;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.preference.*;
import app.yydarlinker.caption.contracts.CaptionContracts.*;
import java.util.*;

/** Full settings behavior + contract-only caption fixture. Synthetic preferences belong only to this app. */
public final class N39UiPreviewActivity extends Activity {
    final Handler handler=new Handler();MeaningTextView caption;TextView counters;FakePort fake;String target="zh-Hans";long position;
    @Override public void onCreate(Bundle state){super.onCreate(state);fake=new FakePort();CaptionActions.install(fake,new CaptionActions.SettingsServices(){public String testApi(){return "FAKE — zero HTTP";}public List<String> models(String endpoint){return Arrays.asList("fake-model","fake-long-model");}});
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(12,12,12,12);setContentView(root);
        caption=new MeaningTextView(this);caption.setTextColor(android.graphics.Color.WHITE);caption.setBackgroundColor(android.graphics.Color.BLACK);root.addView(caption,new LinearLayout.LayoutParams(-1,150));
        LinearLayout controls=new LinearLayout(this);root.addView(controls);Spinner language=new Spinner(this);String[] targets={"zh-Hans","zh-Hant","en","ja","ko","ar","fr","de","es","pt","ru","it","tr","hi"};language.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,targets));controls.addView(language);language.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int i,long id){target=targets[i];position=0;fake.intent++;render();}public void onNothingSelected(android.widget.AdapterView<?> p){}});
        Button next=new Button(this);next.setText("Next / seek");controls.addView(next);next.setOnClickListener(v->{position+=5000;fake.intent++;render();});
        Button rtl=new Button(this);rtl.setText("UI EN / العربية");controls.addView(rtl);rtl.setOnClickListener(v->{android.content.res.Configuration c=new android.content.res.Configuration(getResources().getConfiguration());java.util.Locale locale=getResources().getConfiguration().getLocales().get(0).getLanguage().equals("ar")?java.util.Locale.ENGLISH:java.util.Locale.forLanguageTag("ar");c.setLocales(new android.os.LocaleList(locale));getResources().updateConfiguration(c,getResources().getDisplayMetrics());root.setLayoutDirection(locale.getLanguage().equals("ar")?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);fake.command(Action.UI_LOCALE,locale.toLanguageTag());render();});
        counters=new TextView(this);root.addView(counters);FrameLayout settings=new FrameLayout(this);settings.setId(771039);root.addView(settings,new LinearLayout.LayoutParams(-1,0,1));getFragmentManager().beginTransaction().replace(settings.getId(),new Settings()).commit();
        handler.postDelayed(new Runnable(){public void run(){render();handler.postDelayed(this,1000);}},1000);}
    void render(){if(caption==null||counters==null)return;DeepSeekConfig.Appearance a=DeepSeekConfig.displayStyle(this);int screenWidth=getResources().getDisplayMetrics().widthPixels;float glyph=SubtitleStyleMetrics.targetGlyphHeightPx(a.captionSizeTier,screenWidth,false);caption.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,SubtitleStyleMetrics.textSizePxForGlyphHeight(caption.getPaint(),glyph));caption.setBackgroundColor((Math.round(a.backgroundOpacity*255f/100)<<24));String text="中国的整体军事现代化，比仅让四辆坦克驶过红场更令人印象深刻。没有标点也能显示完整意思。 العربية हिन्दी क्षि 👩🏽‍🚀 e\u0301 Mixed 42 — complete natural caption. ";caption.apply(text+text,"fake-caption-"+target,fake.intent,fake.epoch,position%60000,target);counters.setText("HTTP=0 | intent="+fake.intent+" cache="+fake.epoch+" target="+target+" | "+fake.last);}
    @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
    public static final class Settings extends PreferenceFragment {public void onCreate(Bundle state){super.onCreate(state);addPreferencesFromResource(app.yydarlinker.extension.R.xml.caption_settings);} }
    final class FakePort implements CaptionPort {long intent=1,epoch;String last="fixture ready";public void command(Action a,String value){last=a.name();if(a==Action.CLEAR_CACHE)epoch++;if(a==Action.ACTIVATE||a==Action.VIDEO)intent++;render();}public boolean active(){return true;}public boolean ownsNativeTrack(){return true;}public String restoreTarget(String url){return url;}public String videoId(){return "fixture-video";}public void playback(long at){position=at;render();}}
}
